import os
from google.cloud import aiplatform

def answer_with_context(payload, config=None):
    config = config or {}
    project_id = config.get('project_id') or os.environ.get('GOOGLE_CLOUD_PROJECT')
    location = config.get('location') or os.environ.get('GOOGLE_CLOUD_REGION', 'us-central1')

    aiplatform.init(project=project_id, location=location)

    model = aiplatform.Preview.models.ChatModel.from_pretrained("gemini-1.5-flash-001")

    response = model.predict(
        f"""Using the following context, answer the question.

Context:
{payload['context']}

Question:
{payload['question']}

Answer:""",
        temperature=0.0
    )
    return {'answer': response.text.strip()}

import os
from google.cloud import aiplatform

class VertexAIModelClient:
    def __init__(self, project_id=None, location=None):
        self.project_id = project_id or os.environ.get('GOOGLE_CLOUD_PROJECT')
        self.location = location or os.environ.get('GOOGLE_CLOUD_REGION', 'us-central1')
        if not self.project_id:
            raise ValueError("Google Cloud Project ID not provided and GOOGLE_CLOUD_PROJECT environment variable not set.")

        aiplatform.init(project=self.project_id, location=self.location)

    def get_chat_model(self, model_name="gemini-1.5-flash-001"):
        return aiplatform.Preview.models.ChatModel.from_pretrained(model_name)

    def get_text_embedding_model(self, model_name="text-embedding-004"):
        return aiplatform.Preview.models.TextEmbeddingModel.from_pretrained(model_name)

from typing import Dict, Any, List

class LLMRequest:
    def __init__(self, prompt: str, temperature: float = 0.7, max_output_tokens: int = 1024):
        self.prompt = prompt
        self.temperature = temperature
        self.max_output_tokens = max_output_tokens

    def to_dict(self) -> Dict[str, Any]:
        return {
            "prompt": self.prompt,
            "temperature": self.temperature,
            "max_output_tokens": self.max_output_tokens,
        }

class LLMResponse:
    def __init__(self, text: str, safety_attributes: Dict[str, Any] = None):
        self.text = text
        self.safety_attributes = safety_attributes or {}

    def to_dict(self) -> Dict[str, Any]:
        return {
            "text": self.text,
            "safety_attributes": self.safety_attributes,
        }

class EmbeddingRequest:
    def __init__(self, texts: List[str]):
        self.texts = texts

    def to_dict(self) -> Dict[str, Any]:
        return {
            "instances": [{'content': text} for text in self.texts]
        }

class EmbeddingResponse:
    def __init__(self, embeddings: List[List[float]]):
        self.embeddings = embeddings

    def to_dict(self) -> Dict[str, Any]:
        return {
            "embeddings": self.embeddings
        }

import os
from google.cloud import translate_v3 as translate

def translate_text(payload, config=None):
    config = config or {}
    project_id = config.get('project_id') or os.environ.get('GOOGLE_CLOUD_PROJECT')

    client = translate.TranslationServiceClient()

    location = "global"

    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [payload['text']],
            "mime_type": "text/plain",  # Mime types: text/plain, text/html
            "source_language_code": payload.get('source_language', 'en'),
            "target_language_code": payload['target_language'],
        }
    )

    translated_text = response.translations[0].translated_text
    return {'translated_text': translated_text}
